<header class="site-header">
  <div class="c-wrap header-inner">
    <a href="/" class="logo">Your Name.</a>
    <button class="nav-toggle" aria-label="メニュー" aria-expanded="false">☰</button>
    <nav class="main-nav">
      {links.map((link) => <a href={link.href}>{link.label}</a>)}
    </nav>
