// astro.config.mjs（Preact を使えるようにする）
import { defineConfig } from 'astro/config';
import preact from '@astrojs/preact';

export default defineConfig({
  integrations: [preact()],
});

// src/components/WorksFilter.jsx
import { useState } from 'preact/hooks';
import './WorksFilter.css';

export default function WorksFilter({ works }) {
  const [tag, setTag] = useState('すべて');
  const tags = ['すべて', ...new Set(works.flatMap((w) => w.tags))];
  const shown = tag === 'すべて' ? works : works.filter((w) => w.tags.includes(tag));

  return (
    <div>
      <div class="wf-tags">
        {tags.map((t) => (
          <button class={t === tag ? 'wf-tag is-on' : 'wf-tag'} onClick={() => setTag(t)}>{t}</button>
        ))}
      </div>
      {shown.length === 0 ? (
        <p class="wf-empty">このタグの作品はまだありません。</p>
      ) : (
        <div class="wf-grid">
          {shown.map((w) => (
            <article class="wf-card">
              <h3>{w.title}</h3>
              <p>{w.description}</p>
              <div class="wf-card-tags">{w.tags.map((t) => <span>{t}</span>)}</div>
              <a class="c-link-arrow" href={w.href}>詳しく見る →</a>
            </article>
          ))}
        </div>
      )}
    </div>
  );
}

